import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Environment variable reference","description":"Look up environment variables by shared scope and module, including type, code default, condition, range, purpose, and source location.","frontmatter":{"page_id":"configuration-environment-reference","description":"Look up environment variables by shared scope and module, including type, code default, condition, range, purpose, and source location."},"headers":[],"relativePath":"en/configuration/environment-reference.md","filePath":"en/configuration/environment-reference.md","lastUpdated":1786290726000}'),c={name:"en/configuration/environment-reference.md"};function a(n,t,i,s,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="environment-variable-reference" tabindex="-1">Environment variable reference <a class="header-anchor" href="#environment-variable-reference" aria-label="Permalink to &quot;Environment variable reference&quot;">​</a></h1><p>This page records the public configuration read by the current source. A table “default” is the code default, not a production recommendation. <code>change-me</code>, an empty string, and <code>replace-me</code> from <code>.env.example</code> are not usable secrets.</p><p>Backend processes read <code>.env</code>, with a process environment value taking precedence over the same value in the file. The frontend uses Vite environment files. Backend settings ignore unknown fields. This allows the bundle to provide one superset file, but it also means a misspelled field may not fail at startup.</p><p>A <code>†</code> after a variable means the database can override it through <code>runtime.&lt;lowercase_field_name&gt;</code>. The API refreshes its runtime settings at startup and about every <code>30</code> seconds. The Worker refreshes while polling and claiming work. MCP refreshes shared Core runtime settings during an authenticated request. Without a database value, the process environment or <code>.env</code> value applies.</p><h2 id="source-abbreviations" tabindex="-1">Source abbreviations <a class="header-anchor" href="#source-abbreviations" aria-label="Permalink to &quot;Source abbreviations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Abbreviation</th><th>Current source location</th></tr></thead><tbody><tr><td>C</td><td><code>core/src/ershu/core/config.py</code></td></tr><tr><td>CR</td><td><code>core/src/ershu/services/runtime_settings.py</code></td></tr><tr><td>WR</td><td><code>core/src/ershu/services/worker_runtime_contract.py</code></td></tr><tr><td>A</td><td><code>api/src/ershu/api/runtime_settings.py</code></td></tr><tr><td>W</td><td><code>worker/src/ershu/workers/runtime_settings.py</code></td></tr><tr><td>M</td><td><code>mcp/src/ershu/mcp/runtime_settings.py</code></td></tr><tr><td>F</td><td><code>frontend/lib/api/core.ts</code>, <code>frontend/vite.config.ts</code></td></tr></tbody></table><p>“No explicit range” means the current type can be parsed but the source declares no additional numeric bound or enum. It does not imply that every value is suitable for production.</p><h2 id="shared-backend-process-and-storage-settings" tabindex="-1">Shared backend process and storage settings <a class="header-anchor" href="#shared-backend-process-and-storage-settings" aria-label="Permalink to &quot;Shared backend process and storage settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Modules</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>APP_NAME</code></td><td>Core, API, Worker, MCP</td><td>String</td><td><code>Ershu</code></td><td>No</td><td>No explicit range</td><td>Service display name</td><td>C</td></tr><tr><td><code>APP_VERSION</code></td><td>Core, API, Worker, MCP</td><td>String</td><td><code>0.1.0</code></td><td>No</td><td>No explicit range</td><td>API and service version metadata</td><td>C</td></tr><tr><td><code>ENVIRONMENT</code></td><td>Core, API, Worker, MCP</td><td>String</td><td><code>development</code></td><td>No</td><td><code>prod</code> and <code>production</code> enable production checks</td><td>Controls development behavior and production safety validation</td><td>C, A, M</td></tr><tr><td><code>LOG_LEVEL</code></td><td>API, Worker, MCP</td><td>String</td><td><code>INFO</code></td><td>No</td><td>No explicit enum</td><td>Logging level</td><td>C</td></tr><tr><td><code>DATABASE_URL</code></td><td>API, Worker, MCP, Core tools</td><td>String</td><td><code>postgresql+asyncpg://ershu:ershu_password@localhost:5432/ershu</code></td><td>Must resolve to the deployed database</td><td>No explicit range</td><td>PostgreSQL asynchronous connection URL</td><td>C</td></tr><tr><td><code>DATABASE_POOL_SIZE</code></td><td>API, Worker, MCP, Core tools</td><td>Integer</td><td><code>5</code></td><td>No</td><td>No explicit range</td><td>Persistent database pool size</td><td>C</td></tr><tr><td><code>DATABASE_MAX_OVERFLOW</code></td><td>API, Worker, MCP, Core tools</td><td>Integer</td><td><code>10</code></td><td>No</td><td>No explicit range</td><td>Temporary connections above the pool size</td><td>C</td></tr><tr><td><code>DATABASE_POOL_TIMEOUT_SECONDS</code></td><td>API, Worker, MCP, Core tools</td><td>Integer</td><td><code>30</code></td><td>No</td><td>No explicit range</td><td>Seconds to wait for a database connection</td><td>C</td></tr><tr><td><code>MILVUS_URI</code></td><td>API, Worker, MCP</td><td>String</td><td><code>http://localhost:19530</code></td><td>Must be reachable when vector indexing is used</td><td>No explicit range</td><td>Milvus service address</td><td>C</td></tr><tr><td><code>MILVUS_TOKEN</code></td><td>API, Worker, MCP</td><td>String</td><td>Empty</td><td>Required when Milvus authentication is enabled</td><td>No explicit range</td><td>Milvus credential</td><td>C</td></tr><tr><td><code>MILVUS_DB_NAME</code></td><td>API, Worker, MCP</td><td>String</td><td><code>default</code></td><td>No</td><td>No explicit range</td><td>Milvus database name</td><td>C</td></tr></tbody></table><p>The API, Worker, and MCP should use the same PostgreSQL and Milvus databases. Otherwise, run, permission, revision, and index state will disagree between processes.</p><h2 id="shared-backend-proxy-session-and-secret-settings" tabindex="-1">Shared backend proxy, session, and secret settings <a class="header-anchor" href="#shared-backend-proxy-session-and-secret-settings" aria-label="Permalink to &quot;Shared backend proxy, session, and secret settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Modules</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>PROXY_HEADERS</code></td><td>API, MCP</td><td>Boolean</td><td><code>true</code></td><td>Normally enabled behind a reverse proxy</td><td><code>true</code> or <code>false</code></td><td>Accept proxy headers from permitted sources</td><td>C</td></tr><tr><td><code>FORWARDED_ALLOW_IPS</code></td><td>API, MCP</td><td>String</td><td><code>127.0.0.1</code></td><td>Change when the proxy is not local</td><td>IP or CIDR text accepted by Uvicorn</td><td>Limits which proxies can provide forwarding information</td><td>C</td></tr><tr><td><code>SECRET_KEY</code></td><td>API, MCP</td><td>String</td><td>Invalid <code>change-me</code></td><td>Required at startup</td><td>At least 32 characters; not a known weak value; differs from the other two</td><td>Signs sessions and other server data</td><td>C, A, M</td></tr><tr><td><code>ENCRYPTION_KEY</code></td><td>API, Worker, MCP</td><td>String</td><td>Invalid empty value</td><td>Required at startup</td><td>At least 32 characters; not a known weak value; differs from the other two in API/MCP</td><td>Encrypts model, repository, webhook, and other sensitive values</td><td>C, A, W, M</td></tr><tr><td><code>MCP_KEY_PEPPER</code></td><td>API, MCP</td><td>String</td><td>Invalid empty value</td><td>Required at startup</td><td>At least 32 characters; not a known weak value; differs from the other two</td><td>Independent server secret for MCP key hashing</td><td>C, A, M</td></tr><tr><td><code>SESSION_IDLE_TIMEOUT_MINUTES</code></td><td>API, MCP</td><td>Integer</td><td><code>120</code></td><td>No</td><td>No explicit range</td><td>Determines when a user session is idle</td><td>C</td></tr></tbody></table><p>The API and MCP must share the same three values, and those values must differ from one another. The Worker must at least share <code>ENCRYPTION_KEY</code> so it can read encrypted data written by the API.</p><h2 id="shared-backend-queue-search-and-repository-access" tabindex="-1">Shared backend queue, search, and repository access <a class="header-anchor" href="#shared-backend-queue-search-and-repository-access" aria-label="Permalink to &quot;Shared backend queue, search, and repository access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Modules</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>RUN_QUEUE_LEASE_TIMEOUT_SECONDS</code>†</td><td>API, Worker</td><td>Integer</td><td><code>600</code></td><td>No</td><td><code>300</code>–<code>86400</code></td><td>Decides when a run lease is expired and recoverable</td><td>C, CR</td></tr><tr><td><code>ANALYSIS_RUN_RETENTION_COUNT</code>†</td><td>API, Worker</td><td>Integer</td><td><code>50</code></td><td>No</td><td><code>1</code>–<code>10000</code></td><td>Completed, failed, or cancelled runs retained per project; active runs are never removed</td><td>C, CR</td></tr><tr><td><code>SEARCH_INDEX_BATCH_SIZE</code>†</td><td>API, Worker</td><td>Integer</td><td><code>2000</code></td><td>No</td><td><code>100</code>–<code>20000</code></td><td>Maximum search chunks rebuilt and written per batch</td><td>C, CR</td></tr><tr><td><code>REPOSITORY_STORAGE_PATH</code>†</td><td>API, Worker, MCP</td><td>String</td><td><code>.ershu/repo_cache</code></td><td>No</td><td>Non-empty, at most 255 trimmed characters</td><td>Root for remote repository cache and controlled workspaces</td><td>C, CR</td></tr><tr><td><code>TRUSTED_LOCAL_PATHS</code>†</td><td>API, Worker, MCP</td><td>String list; comma- or newline-delimited text is also accepted</td><td><code>[]</code></td><td>Required for local repositories</td><td>At most 50 items</td><td>Allowed roots for registered local repositories</td><td>C, CR</td></tr><tr><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code>†</td><td>API, Worker, MCP</td><td>Boolean</td><td><code>false</code></td><td>Development only</td><td>Must be <code>false</code> in production</td><td>Allows local paths without allowlist or <code>.git</code> coverage during development</td><td>C, CR</td></tr><tr><td><code>GIT_COMMAND_TIMEOUT_SECONDS</code>†</td><td>API, Worker, MCP</td><td>Integer</td><td><code>120</code></td><td>No</td><td><code>10</code>–<code>3600</code></td><td>Timeout for Git clone, fetch, checkout, and cache-lock waits</td><td>C, CR</td></tr><tr><td><code>GIT_ALLOWED_HOSTS</code>†</td><td>API, Worker, MCP</td><td>String list</td><td><code>[]</code></td><td>Set according to remote-access policy</td><td>At most 50 items</td><td>Remote hosts permitted for clone or fetch</td><td>C, CR</td></tr><tr><td><code>ALLOW_INSECURE_GIT_URLS</code>†</td><td>API, Worker, MCP</td><td>Boolean</td><td><code>false</code></td><td>Enable only with an explicit isolated-network risk decision</td><td><code>true</code> or <code>false</code></td><td>Allows insecure Git URLs</td><td>C, CR</td></tr><tr><td><code>ALLOW_FILE_GIT_URLS</code>†</td><td>API, Worker, MCP</td><td>Boolean</td><td><code>false</code></td><td>Enable when <code>file:</code> Git URLs are required</td><td><code>true</code> or <code>false</code></td><td>Allows <code>file:</code> Git URLs</td><td>C, CR</td></tr><tr><td><code>GITHUB_TOKEN</code></td><td>API, Worker, MCP</td><td>String</td><td>Empty</td><td>Only when no repository credential exists and the remote requires one</td><td>No explicit range</td><td>Fallback GitHub repository token</td><td>C</td></tr><tr><td><code>GITLAB_TOKEN</code></td><td>API, Worker, MCP</td><td>String</td><td>Empty</td><td>Only when no repository credential exists and the remote requires one</td><td>No explicit range</td><td>Fallback GitLab repository token</td><td>C</td></tr></tbody></table><p>MCP and Worker may keep separate caches for remote repositories; they do not need to share <code>REPOSITORY_STORAGE_PATH</code>. A local path is not copied between hosts, so every process that uses it must be able to reach it.</p><h2 id="api-only-settings" tabindex="-1">API-only settings <a class="header-anchor" href="#api-only-settings" aria-label="Permalink to &quot;API-only settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>HOST</code></td><td>String</td><td><code>127.0.0.1</code></td><td>No</td><td>No explicit range</td><td>API listen address</td><td>A</td></tr><tr><td><code>PORT</code></td><td>Integer</td><td><code>8000</code></td><td>No</td><td>No explicit code range</td><td>API listen port</td><td>A</td></tr><tr><td><code>REDIS_URL</code></td><td>String</td><td><code>redis://localhost:6379/0</code></td><td>Non-empty and reachable when running the Poller</td><td>No explicit range</td><td>Distributed lease for the repository Poller</td><td>A, <code>api/src/ershu/api/poller.py</code></td></tr><tr><td><code>CORS_ORIGINS</code></td><td>String list</td><td><code>[&quot;http://localhost:3000&quot;]</code></td><td>Configure for cross-origin frontend access</td><td>No explicit item limit</td><td>Origins allowed to call the API with credentials</td><td>A</td></tr><tr><td><code>ACCESS_TOKEN_EXPIRE_MINUTES</code></td><td>Integer</td><td><code>30</code></td><td>No</td><td>At least <code>1</code></td><td>Access-token lifetime in minutes</td><td>A</td></tr><tr><td><code>SESSION_ABSOLUTE_TIMEOUT_HOURS</code></td><td>Integer</td><td><code>168</code></td><td>No</td><td>At least <code>1</code></td><td>Absolute session lifetime in hours</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_NAME</code></td><td>String</td><td><code>ershu_session</code></td><td>No</td><td>No explicit range</td><td>Session cookie name</td><td>A</td></tr><tr><td><code>REFRESH_COOKIE_NAME</code></td><td>String</td><td><code>ershu_refresh</code></td><td>No</td><td>No explicit range</td><td>Refresh cookie name</td><td>A</td></tr><tr><td><code>CSRF_COOKIE_NAME</code></td><td>String</td><td><code>ershu_csrf</code></td><td>Must match the frontend setting</td><td>No explicit range</td><td>CSRF cookie name</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_SECURE</code></td><td>Boolean</td><td><code>false</code></td><td>Must be <code>true</code> in production</td><td><code>true</code> or <code>false</code></td><td>Restricts the cookie to secure connections</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_SAMESITE</code></td><td>String</td><td><code>lax</code></td><td>Validated in production</td><td><code>lax</code>, <code>strict</code>, or <code>none</code> in production</td><td>Cookie SameSite policy</td><td>A</td></tr><tr><td><code>STREAM_TICKET_EXPIRE_SECONDS</code>†</td><td>Integer</td><td><code>300</code></td><td>No</td><td><code>30</code>–<code>3600</code></td><td>Lifetime of a newly issued chat-stream ticket</td><td>A</td></tr><tr><td><code>OPAQUE_SERVER_SETUP</code></td><td>String</td><td>Empty</td><td>Required and stable in production</td><td>At least 32 characters and not a weak value</td><td>Server setup for OPAQUE password registration and sign-in</td><td>A</td></tr><tr><td><code>POLLER_INTERVAL_SECONDS</code></td><td>Integer</td><td><code>30</code></td><td>Used by the Poller process</td><td><code>5</code>–<code>3600</code></td><td>Minimum time between repository schedule scans</td><td>A</td></tr><tr><td><code>POLLER_LEASE_SECONDS</code></td><td>Integer</td><td><code>120</code></td><td>Used by the Poller process</td><td><code>30</code>–<code>3600</code></td><td>Redis Poller lease duration</td><td>A</td></tr><tr><td><code>POLLER_BATCH_SIZE</code></td><td>Integer</td><td><code>100</code></td><td>Used by the Poller process</td><td><code>1</code>–<code>1000</code></td><td>Maximum due repositories checked in one cycle</td><td>A</td></tr></tbody></table><p>Production also requires HTTPS. When a reverse proxy terminates HTTPS, configure forwarding and allowed proxy sources correctly instead of disabling cookie safety checks.</p><h2 id="worker-queue-analysis-and-user-question-settings" tabindex="-1">Worker queue, analysis, and user-question settings <a class="header-anchor" href="#worker-queue-analysis-and-user-question-settings" aria-label="Permalink to &quot;Worker queue, analysis, and user-question settings&quot;">​</a></h2><p>Every setting in this section carries <code>†</code> and can be overridden by a database runtime setting.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>RUN_QUEUE_POLL_INTERVAL_MS</code>†</td><td>Integer</td><td><code>1000</code></td><td>No</td><td><code>100</code>–<code>60000</code></td><td>Interval between Worker queue checks</td><td>WR, W</td></tr><tr><td><code>MAX_PARALLEL_REPOSITORY_RUNS</code>†</td><td>Integer</td><td><code>3</code></td><td>No</td><td><code>1</code>–<code>100</code></td><td>Hard repository concurrency cap for full-project facts and document stages</td><td>WR, W</td></tr><tr><td><code>SEARCH_INDEX_BACKGROUND_ENABLED</code>†</td><td>Boolean</td><td><code>true</code></td><td>No</td><td><code>true</code> or <code>false</code></td><td>Lets a run complete before background search-index refresh finishes</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_IMPORT_GRAPH_MAX_FILES</code>†</td><td>Integer</td><td><code>20000</code></td><td>No</td><td><code>100</code>–<code>100000</code>, or <code>-1</code> for no count limit</td><td>Maximum source files inspected for import relationships</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_IMPORT_GRAPH_MAX_EDGES</code>†</td><td>Integer</td><td><code>100000</code></td><td>No</td><td><code>1000</code>–<code>1000000</code>, or <code>-1</code> for no count limit</td><td>Maximum import relationships retained per repository</td><td>WR, W</td></tr><tr><td><code>ENABLE_ASK_USER</code>†</td><td>Boolean</td><td><code>false</code></td><td>No</td><td><code>true</code> or <code>false</code></td><td>Allows the analysis agent to ask a user during new tool turns</td><td>WR, W</td></tr><tr><td><code>ASK_USER_TIMEOUT_MINUTES</code>†</td><td>Integer</td><td><code>720</code></td><td>Used when questions are enabled</td><td><code>1</code>–<code>10080</code></td><td>Minutes during which a question remains actionable</td><td>WR, W</td></tr><tr><td><code>ASK_USER_MAX_QUESTIONS_PER_RUN</code>†</td><td>Integer</td><td><code>3</code></td><td>Used when questions are enabled</td><td><code>0</code>–<code>100</code></td><td>Maximum questions in one run</td><td>WR, W</td></tr><tr><td><code>ASK_USER_MIN_ITERATIONS_BETWEEN_QUESTIONS</code>†</td><td>Integer</td><td><code>20</code></td><td>Used when questions are enabled</td><td><code>0</code>–<code>10000</code></td><td>Minimum agent-loop iterations between questions in one run</td><td>WR, W</td></tr></tbody></table><p>Setting either import-graph count to <code>-1</code> removes only that count limit. Traversal safety and other limits remain active.</p><h2 id="worker-lsp-and-dependency-preparation" tabindex="-1">Worker LSP and dependency preparation <a class="header-anchor" href="#worker-lsp-and-dependency-preparation" aria-label="Permalink to &quot;Worker LSP and dependency preparation&quot;">​</a></h2><p>LSP means Language Server Protocol. Language servers run inside read-only, offline Docker sandboxes. Optional dependency preparation uses a separate short-lived download sandbox.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range or options</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>REPOSITORY_LSP_ENABLED</code>†</td><td>Boolean</td><td><code>false</code></td><td>Enable for language services</td><td><code>true</code> or <code>false</code></td><td>Permits new LSP sessions</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_LSP_RUNTIME</code>†</td><td>Enum</td><td><code>docker</code></td><td>Used when LSP is enabled</td><td><code>docker</code> only</td><td>Selects the LSP runtime</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_LSP_LANGUAGES</code>†</td><td>String list</td><td><code>[&quot;python&quot;]</code></td><td>Configure when LSP is enabled</td><td>At most 50 items; current adapters are <code>python</code>, <code>typescript</code>, <code>go</code>, <code>rust</code>, <code>clangd</code>, and <code>java</code></td><td>Enables adapter groups; <code>typescript</code> also covers TSX and JavaScript</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_LSP_DEFAULT_MODE</code>†</td><td>Enum</td><td><code>strict</code></td><td>Used when LSP is enabled</td><td><code>strict</code> or <code>semantic</code></td><td>Default mode for new capability activation</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_LSP_ALLOW_SEMANTIC_MODE</code>†</td><td>Boolean</td><td><code>false</code></td><td>Must be explicitly enabled for <code>semantic</code></td><td><code>true</code> or <code>false</code></td><td>Allows semantic-mode capability activation</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_RESOLUTION_MODE</code>†</td><td>Enum</td><td><code>disabled</code></td><td>Change to <code>managed</code> to prepare dependencies</td><td><code>disabled</code> or <code>managed</code></td><td>Controls separate dependency preparation before LSP</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_SOURCE_POLICY</code>†</td><td>Enum</td><td><code>configured_or_public</code></td><td>Used during managed preparation</td><td><code>configured_only</code>, <code>configured_or_public</code>, or <code>public_only</code></td><td>Selects enterprise and public dependency-source policy</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_ALLOW_INSECURE_SOURCES</code>†</td><td>Boolean</td><td><code>false</code></td><td>Enable only for required HTTP sources in an isolated network</td><td><code>true</code> or <code>false</code></td><td>Allows insecure dependency-source URLs</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_PREPARE_TIMEOUT_SECONDS</code>†</td><td>Integer</td><td><code>600</code></td><td>Used during managed preparation</td><td><code>30</code>–<code>3600</code></td><td>Timeout for each dependency-preparation command</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_PREPARE_MAX_MB</code>†</td><td>Integer</td><td><code>2048</code></td><td>Used during managed preparation</td><td><code>64</code>–<code>16384</code></td><td>Prepared dependency size retained for one language session</td><td>WR, W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_CA_BUNDLE_PATH</code></td><td>Nullable string</td><td>Empty</td><td>Set when a private source needs an additional CA</td><td>Environment-only; no explicit length range</td><td>Path to an additional PEM CA bundle on the Worker host</td><td>W</td></tr></tbody></table><p>Managed dependency preparation currently recognizes locked Go, npm, Python, and Cargo dependencies. Java Maven and Gradle are not part of this path.</p><h2 id="worker-lsp-container-resources-and-reference-scanning" tabindex="-1">Worker LSP container resources and reference scanning <a class="header-anchor" href="#worker-lsp-container-resources-and-reference-scanning" aria-label="Permalink to &quot;Worker LSP container resources and reference scanning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>LSP_DOCKER_BIN</code>†</td><td>String</td><td><code>docker</code></td><td>Must be executable when LSP is enabled</td><td>Non-empty, at most 255 characters</td><td>Docker command name or path</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_UID</code>†</td><td>Integer</td><td><code>1000</code></td><td>No</td><td><code>0</code>–<code>65535</code></td><td>User identifier in new containers</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_GID</code>†</td><td>Integer</td><td><code>1000</code></td><td>No</td><td><code>0</code>–<code>65535</code></td><td>Group identifier in new containers</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_CPUS</code>†</td><td>String</td><td><code>2</code></td><td>No</td><td>Non-empty, at most 255 characters</td><td>CPU limit for new LSP containers</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_MEMORY</code>†</td><td>String</td><td><code>2g</code></td><td>No</td><td>Non-empty, at most 255 characters</td><td>Memory limit for new LSP containers</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_PIDS_LIMIT</code>†</td><td>Integer</td><td><code>256</code></td><td>No</td><td><code>32</code>–<code>4096</code></td><td>Process-count limit for new containers</td><td>WR, W</td></tr><tr><td><code>LSP_DOCKER_TMPFS_MB</code>†</td><td>Integer</td><td><code>512</code></td><td>No</td><td><code>64</code>–<code>8192</code></td><td>Temporary filesystem size in new containers</td><td>WR, W</td></tr><tr><td><code>LSP_IDLE_TIMEOUT_SECONDS</code>†</td><td>Integer</td><td><code>300</code></td><td>No</td><td><code>30</code>–<code>7200</code></td><td>Idle-session reaping threshold</td><td>WR, W</td></tr><tr><td><code>LSP_SESSION_MAX_SECONDS</code>†</td><td>Integer</td><td><code>3600</code></td><td>No</td><td><code>60</code>–<code>28800</code></td><td>Maximum lifetime of one LSP session</td><td>WR, W</td></tr><tr><td><code>LSP_MAX_SESSIONS_PER_RUN</code>†</td><td>Integer</td><td><code>3</code></td><td>No</td><td><code>1</code>–<code>20</code></td><td>Maximum LSP sessions in one analysis run</td><td>WR, W</td></tr><tr><td><code>LSP_MAX_SESSIONS_PER_WORKER</code>†</td><td>Integer</td><td><code>8</code></td><td>No</td><td><code>1</code>–<code>100</code></td><td>Maximum LSP sessions in one Worker</td><td>WR, W</td></tr><tr><td><code>LSP_IMAGES</code>†</td><td>String map</td><td>Six default adapter images listed below</td><td>An image is required for each enabled language</td><td>At most 50 items; keys and values are non-empty</td><td>Maps adapter groups to Docker images</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_MAX_SYMBOLS</code>†</td><td>Integer</td><td><code>200</code></td><td>No</td><td><code>10</code>–<code>5000</code>, or <code>-1</code></td><td>High-value symbols queried for semantic references per repository</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_MAX_LOCATIONS_PER_SYMBOL</code>†</td><td>Integer</td><td><code>80</code></td><td>No</td><td><code>1</code>–<code>5000</code>, or <code>-1</code></td><td>Reference locations accepted for one symbol</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_MAX_EDGES</code>†</td><td>Integer</td><td><code>2000</code></td><td>No</td><td><code>100</code>–<code>100000</code>, or <code>-1</code></td><td>Callable-reference edges retained per repository</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_MAX_MODULE_EDGES</code>†</td><td>Integer</td><td><code>400</code></td><td>No</td><td><code>0</code>–<code>50000</code>, or <code>-1</code></td><td>Module-level reference edges retained per repository</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_SYMBOL_TIMEOUT_SECONDS</code>†</td><td>Integer</td><td><code>6</code></td><td>No</td><td><code>1</code>–<code>120</code></td><td>Timeout for one semantic-reference query</td><td>WR, W</td></tr><tr><td><code>LSP_REFERENCE_TOTAL_TIMEOUT_SECONDS</code>†</td><td>Integer</td><td><code>300</code></td><td>No</td><td><code>30</code>–<code>7200</code></td><td>Total semantic-reference budget per repository</td><td>WR, W</td></tr></tbody></table><p>The code defaults for <code>LSP_IMAGES</code> are:</p><table tabindex="0"><thead><tr><th>Adapter group</th><th>Default image</th></tr></thead><tbody><tr><td><code>python</code></td><td><code>ershu-lsp-python:basedpyright</code></td></tr><tr><td><code>typescript</code></td><td><code>ershu-lsp-typescript:typescript-language-server</code></td></tr><tr><td><code>go</code></td><td><code>ershu-lsp-go:gopls</code></td></tr><tr><td><code>rust</code></td><td><code>ershu-lsp-rust:rust-analyzer</code></td></tr><tr><td><code>clangd</code></td><td><code>ershu-lsp-clangd:clangd</code></td></tr><tr><td><code>java</code></td><td><code>ershu-lsp-java:jdtls</code></td></tr></tbody></table><p>For the four reference counts, <code>-1</code> removes only the count limit. Per-symbol and total time budgets still apply.</p><h2 id="mcp-only-settings" tabindex="-1">MCP-only settings <a class="header-anchor" href="#mcp-only-settings" aria-label="Permalink to &quot;MCP-only settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range or options</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>MCP_HOST</code></td><td>String</td><td><code>127.0.0.1</code></td><td>No</td><td>No explicit range</td><td>MCP listen address</td><td>M</td></tr><tr><td><code>MCP_PORT</code></td><td>Integer</td><td><code>8001</code></td><td>No</td><td>No explicit code range</td><td>MCP listen port</td><td>M</td></tr><tr><td><code>MCP_BUILD_COMMIT</code></td><td>String</td><td>Empty</td><td>Required in production</td><td>Empty or an exact 40-character hexadecimal commit; production cannot be empty</td><td>Reports the exact source commit used to build the process</td><td>M</td></tr><tr><td><code>MCP_ENABLE_DNS_REBINDING_PROTECTION</code></td><td>Boolean</td><td><code>true</code></td><td>Must be <code>true</code> in production</td><td><code>true</code> or <code>false</code></td><td>Enables transport-level DNS rebinding protection</td><td>M</td></tr><tr><td><code>MCP_ALLOWED_HOSTS</code></td><td>String list</td><td><code>[&quot;127.0.0.1:*&quot;,&quot;localhost:*&quot;,&quot;[::1]:*&quot;,&quot;testserver&quot;]</code></td><td>Non-empty in production; add external hosts</td><td>No explicit item limit</td><td>Permitted request Host values</td><td>M</td></tr><tr><td><code>MCP_ALLOWED_ORIGINS</code></td><td>String list</td><td><code>[&quot;http://127.0.0.1:*&quot;,&quot;http://localhost:*&quot;,&quot;http://[::1]:*&quot;]</code></td><td>Non-empty in production; add external origins</td><td>No explicit item limit</td><td>Permitted request Origin values</td><td>M</td></tr></tbody></table><p>Production MCP must also be able to read installed <code>ershu-mcp</code> package metadata. This is not an environment variable, but the process still refuses to start when it is missing.</p><h2 id="frontend-build-and-development-settings" tabindex="-1">Frontend build and development settings <a class="header-anchor" href="#frontend-build-and-development-settings" aria-label="Permalink to &quot;Frontend build and development settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Code default</th><th>Required or conditional</th><th>Range</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td>String</td><td><code>/api/v1</code></td><td>Change when the API is not on the same-origin path</td><td>No explicit range</td><td>Browser API base path</td><td>F</td></tr><tr><td><code>VITE_CSRF_COOKIE_NAME</code></td><td>String</td><td><code>ershu_csrf</code></td><td>Must match API <code>CSRF_COOKIE_NAME</code></td><td>No explicit range</td><td>Cookie name used by the frontend for CSRF</td><td>F</td></tr><tr><td><code>VITE_DEV_API_PROXY</code></td><td>String</td><td><code>http://localhost:8000</code></td><td>Change for the actual API during development</td><td>No explicit range</td><td>Vite target for <code>/api</code></td><td>F</td></tr><tr><td><code>VITE_DEV_MCP_PROXY</code></td><td>String</td><td><code>http://127.0.0.1:8001</code></td><td>Change for the actual MCP service during development</td><td>No explicit range</td><td>Vite target for <code>/mcp</code></td><td>F</td></tr></tbody></table><p>Vite embeds these values in the frontend artifact. Never put a secret in a <code>VITE_</code> variable.</p><h2 id="optional-core-real-service-test-variables" tabindex="-1">Optional Core real-service test variables <a class="header-anchor" href="#optional-core-real-service-test-variables" aria-label="Permalink to &quot;Optional Core real-service test variables&quot;">​</a></h2><p>These values come from <code>core/.env.example</code>. They are only for explicitly enabled tests against real PostgreSQL or Milvus services, not API, Worker, or MCP runtime configuration.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Example default</th><th>Condition</th><th>Purpose</th><th>Source</th></tr></thead><tbody><tr><td><code>ERSHU_TEST_POSTGRES_URL</code></td><td>String</td><td>Empty</td><td>Set for real PostgreSQL tests</td><td>Test database URL</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_URI</code></td><td>String</td><td>Empty</td><td>Set for real Milvus tests</td><td>Test Milvus address</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_TOKEN</code></td><td>String</td><td>Empty</td><td>Set when test Milvus uses authentication</td><td>Test Milvus credential</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_DB_NAME</code></td><td>String</td><td><code>default</code></td><td>Used for real Milvus tests</td><td>Test Milvus database</td><td><code>core/.env.example</code></td></tr></tbody></table><h2 id="four-common-mistakes" tabindex="-1">Four common mistakes <a class="header-anchor" href="#four-common-mistakes" aria-label="Permalink to &quot;Four common mistakes&quot;">​</a></h2><ol><li>Secret placeholders in <code>.env.example</code> are not runnable defaults. API and MCP reject weak secrets, and Worker rejects a weak <code>ENCRYPTION_KEY</code>.</li><li>Model channels are not environment variables. Administrators save LLM, embedding, and reranker channels through the web interface or API.</li><li>Database runtime overrides apply only to variables marked <code>†</code>. Database addresses, secrets, cookies, CORS, and MCP transport-security boundaries remain deployment environment settings.</li><li>Runtime changes are not retroactive rewrites. Most values affect new polls, sessions, scans, containers, or index batches; they do not reconfigure work already in progress.</li></ol>',43)])])}const S=d(c,[["render",a]]);export{p as __pageData,S as default};
